<header class="page-header"><div><p class="eyebrow">Data tools</p><h1>Review import</h1><p><?= $escape($preview['valid_count']) ?> valid row<?= $preview['valid_count']===1?'':'s' ?> and <?= $escape($preview['invalid_count']) ?> rejected.</p></div></header><div class="table-scroll"><table><thead><tr><th>Line</th><th>Result</th><th>Details</th></tr></thead><tbody><?php foreach($preview['rows'] as $row): ?><tr><td><?= $escape($row['line']) ?></td><td><?= $row['errors']===[]?'Will import':'Rejected' ?></td><td><?= $escape($row['errors']===[]?'New prospect':implode(' ',$row['errors'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($preview['invalid_count']>0): ?><p class="validation-summary">Correct all rejected rows and upload a new file. No rows can be committed from this preview.</p><?php elseif($preview['valid_count']>0): ?><form method="post" action="<?= $escape($commitUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="preview_token" value="<?= $escape($preview['token']) ?>"><button>Commit <?= $escape($preview['valid_count']) ?> valid rows</button></form><?php endif; ?><form class="inline-form" method="post" action="<?= $escape($cancelUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><button class="button--danger">Discard preview</button></form><p><a href="<?= $escape($importUrl) ?>">Choose another file</a></p>
